L["Add your consumables, put them in order, set each one up."] = "Añade tus consumibles, ordénalos y configura cada uno."
L["Add your own lines to the bag macros. They are kept after the item, whatever is in your bags."] = "Añade tus propias líneas a las macros de bolsa. Se mantienen después del objeto, tengas lo que tengas en las bolsas."
L["Added %d consumable to the Consumable Bar."] = "Se ha añadido %d consumible a la barra de consumibles."
