L["Added %d of %d: %s."] = "Añadidos %d de %d: %s."
L["Added %d."] = "Añadidos %d."
L["Added %s to this character. Drag it to a bar from the game's macro window (/macro)."] = "%s añadida a este personaje. Arrástrala a una barra desde la ventana de macros del juego (/macro)."
L["Added %s to your BiS %s as #%d."] = "%s añadido a tu BiS de %s como n.º %d."
