L["Item tooltips show the item's price at your last auction house scan, for one of it, and how long ago that was. Scan with the Scan Prices button on the auction house."] = "Las descripciones de objetos muestran el precio del objeto en tu último escaneo de la casa de subastas, por unidad, y hace cuánto fue. Escanea con el botón Escanear precios de la casa de subastas."
