L["One number for a character's gear, on the item level scale: 26.4 means gear worth a set of level 26 epics. Your own is always on the BiS List's paperdoll."] = "Un número para el equipo de un personaje, en la escala de nivel de objeto: 26,4 significa equipo equivalente a un conjunto de épicos de nivel 26. El tuyo está siempre en el muñeco de la lista BiS."
L["One whisper per line, picked at random; {buff} and {name} are filled in."] = "Un susurro por línea, elegido al azar; {buff} y {name} se rellenan."
