L["Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan."] = "Abre en esta ventana el enlace de profesión de otro jugador, para encargarle fabricaciones. Elige una receta, indica cuántas fabricaciones, marca los materiales que aportas (o escribe cuántos) y pulsa Añadir al pedido. El pedido de la derecha tiene una propina sugerida por fabricación que puedes cambiar; Pedir envía al artesano un mensaje por fabricación con la cantidad, tus materiales y la propina: por el chat de grupo si está en tu grupo o, si no, como susurro. Los precios y la propina necesitan un escaneo de la casa de subastas."
L["Opens its settings and leaves the HUD Editor."] = "Abre su configuración y sale del Editor de HUD."
