L["Opens the copy card on a sample spell. Select the ID or link, then Ctrl+C."] = "Abre la tarjeta de copia sobre un hechizo de ejemplo. Selecciona la ID o el enlace y pulsa Ctrl+C."
L["Opens the Dungeon Journal's Quest Tracker settings."] = "Abre la configuración del seguimiento de misiones del Diario de mazmorras."
L["Opens the HUD Editor: click another Naowh Forever element for the bar to move with."] = "Abre el Editor de HUD: haz clic en otro elemento de Naowh Forever con el que se moverá la barra."
L["Opens the Library Books tracker's settings."] = "Abre la configuración del seguimiento de Libros de la biblioteca."
L["Opens the planner on its Builds tab."] = "Abre el planificador en su pestaña Builds."
L["Opens the quest tracker out in the world, on the dungeon your quests are for."] = "Abre el seguimiento de misiones en el mundo, en la mazmorra a la que corresponden tus misiones."
