L["Plays the map ping and names the book in chat when you come within range of one you still need. Once per book, until you walk away and come back."] = "Reproduce el ping del mapa y nombra el libro en el chat cuando te acercas a uno que aún necesitas. Una vez por libro, hasta que te alejes y vuelvas."
