L["Put back every setting this page has changed?"] = "¿Restaurar todas las opciones que ha cambiado esta página?"
L["put down what you are holding first."] = "suelta antes lo que tienes en la mano."
L["Put every %s weight back to the defaults?"] = "¿Restablecer todos los pesos de %s a sus valores predeterminados?"
L["Put every setting back to how it was before the onboarding?"] = "¿Devolver todas las opciones a como estaban antes de la configuración inicial?"
L["Put every setting in this profile back to its default."] = "Devuelve todas las opciones de este perfil a su valor predeterminado."
L["Put on in cities and inns, and taken off again when you leave."] = "Se pone en ciudades y posadas, y se quita de nuevo al salir."
L["Put on while you ride, and the set you had on goes back when you dismount."] = "Se pone mientras vas montado, y el conjunto que llevabas vuelve al desmontar."
L["Put the XP Bar colors back to their defaults?"] = "¿Restablecer los colores de la barra de PX a sus valores predeterminados?"
L["Put the XP Bar's size and texts back to their defaults?"] = "¿Restablecer el tamaño y los textos de la barra de PX a sus valores predeterminados?"
L["Put this bar back in"] = "Volver a incluir esta barra"
L["Puts a raid marker on your focus. Pressing the macro again on the same focus clears the marker."] = "Pone una marca de banda en tu foco. Pulsar la macro de nuevo sobre el mismo foco quita la marca."
L["Puts back every setting this page has changed, to the value you had before."] = "Restaura todas las opciones que ha cambiado esta página al valor que tenías antes."
L["Puts back everything changed since the HUD Editor opened."] = "Restaura todo lo cambiado desde que se abrió el Editor de HUD."
L["Puts back the last change. Ctrl + Z."] = "Deshace el último cambio. Ctrl + Z."
L["Puts both back where the game shows them."] = "Vuelve a poner ambos donde los muestra el juego."
L["Puts every weight of this spec back to the defaults. Asks first."] = "Restablece todos los pesos de esta especialización a sus valores predeterminados. Pregunta antes."
L["Puts food, drink and potions 10 or more levels below you, marked with a clock, first."] = "Pone primero, marcadas con un reloj, la comida, bebida y pociones de 10 o más niveles por debajo de ti."
L["Puts the bar back on the screen."] = "Devuelve la barra a la pantalla."
L["Puts the bar's buttons back as they came: the Dungeon Journal and Discovery on the left, the BiS List and Training Planner on the right."] = "Devuelve los botones de la barra a como venían: el Diario de mazmorras y Descubrimiento a la izquierda, la lista BiS y el Planificador de entrenamiento a la derecha."
L["Puts the card back above the middle of the screen, where it starts."] = "Devuelve la tarjeta encima del centro de la pantalla, donde empieza."
L["Puts the cheapest item at the far end of the row instead of next to its anchor."] = "Pone el objeto más barato al extremo de la fila en lugar de junto a su ancla."
L["Puts the cheapest item on your cursor, to drop or sell."] = "Pone el objeto más barato en tu cursor, para tirarlo o venderlo."
L["Puts the count just past the icon's edge."] = "Pone el recuento justo fuera del borde del icono."
L["Puts the key just past the icon's edge."] = "Pone la tecla justo fuera del borde del icono."
L["Puts the materials for that many crafts on your shopping list: every checked reagent that vendors do not sell, whatever is in your bags. Uncheck a reagent to leave it out. At the auction house the list shows beside it, to check the prices and buy it all."] = "Pone en tu lista de la compra los materiales para esa cantidad de fabricaciones: cada componente marcado que no venden los vendedores, tengas lo que tengas en las bolsas. Desmarca un componente para dejarlo fuera. En la casa de subastas la lista aparece al lado, para comprobar los precios y comprarlo todo."
L["Puts the popup back where it first showed."] = "Devuelve la ventana a donde apareció por primera vez."
L["Puts the quiz back where it first opened."] = "Devuelve el test a donde se abrió por primera vez."
L["Puts the text just past the icon's edge."] = "Pone el texto justo fuera del borde del icono."
L["Puts this recipe on the order on the right, with the number of crafts and the materials you bring. Changes made here after adding it change the order too. Up to %d recipes per order."] = "Pone esta receta en el pedido de la derecha, con el número de fabricaciones y los materiales que aportas. Los cambios hechos aquí después de añadirla también cambian el pedido. Hasta %d recetas por pedido."
L["Puts this set on. In combat, it goes on when the fight ends."] = "Se pone este conjunto. En combate, se pone al terminar el combate."
L["Puts your settings to one of Naowh's setups, or walks you through them again."] = "Ajusta tu configuración a una de las de Naowh o te guía de nuevo por ellas."
