L["The Naowh Forever N next to the name of Naowh, the developers, the moderators and our Legendary and Epic patrons in chat."] = "La N de Naowh Forever junto al nombre de Naowh, los desarrolladores, los moderadores y nuestros mecenas legendarios y épicos en el chat."
