L["Theme presets for the addon's windows and HUD frames, plus a Custom option for your own colors. If text gets hard to read, pick Naowh (default). Saved for this computer.|n|nTakes effect after a /reload."] = "Temas predefinidos para las ventanas y marcos del HUD del addon, más una opción Personalizado para tus propios colores. Si el texto cuesta de leer, elige Naowh (predeterminado). Guardado para este ordenador.|n|nSe aplica tras un /reload."
