L["What a point of each stat is worth to your spec."] = "Lo que vale un punto de cada estadística para tu especialización."
L["What a waypoint from the Discovery window or the tracker does."] = "Lo que hace un punto de ruta de la ventana de Descubrimiento o del seguimiento."
L["What a zone's page in the Quest List window lists."] = "Lo que lista la página de una zona en la ventana de la lista de misiones."
L["What a zone's page in the Quest List window lists. Kills count from when Discovery is on: Shift-click a rare there to tick off one you killed before."] = "Lo que lista la página de una zona en la ventana de la lista de misiones. Las muertes cuentan desde que Descubrimiento está activado: Mayús+clic en un raro ahí para marcar uno que mataste antes."
L["What changed in recent builds."] = "Lo que ha cambiado en las versiones recientes."
L["WHAT COMES ACROSS"] = "LO QUE SE INCLUYE"
L["What drops in every dungeon and raid."] = "Lo que cae en cada mazmorra y banda."
L["What each line is worth, in gold, silver and copper."] = "Lo que vale cada línea, en oro, plata y cobre."
L["What each stack is worth, in its largest coin, under its icon."] = "Lo que vale cada montón, en su moneda mayor, bajo su icono."
L["What each stat is worth to your spec: change them as you like."] = "Lo que vale cada estadística para tu especialización: cámbialas a tu gusto."
L["What each stat is worth to your spec: the BiS List's upgrade percents and enchants come from them. Change the weights in the Stat Weights window, from the scales on the BiS List's title bar."] = "Lo que vale cada estadística para tu especialización: de ahí salen los porcentajes de mejora y los encantamientos de la lista BiS. Cambia los pesos en la ventana Pesos de estadísticas, desde la balanza de la barra de título de la lista BiS."
L["What each stat is worth to your spec: the upgrade percents and enchants come from them. Set your own."] = "Lo que vale cada estadística para tu especialización: de ahí salen los porcentajes de mejora y los encantamientos. Pon los tuyos."
L["What Happened"] = "Lo que ha pasado"
L["What happens when you open a vendor. Both work whether or not the Restock Reminder is on."] = "Lo que pasa al abrir un vendedor. Ambos funcionan esté o no activado el Recordatorio de reposición."
L["What It Lists"] = "Lo que lista"
L["What it lists"] = "Lo que lista"
L["What it puts on you: a buff, or an enchant on a weapon."] = "Lo que te aplica: un beneficio o un encantamiento en un arma."
L["What it says while you are in stealth."] = "Lo que dice mientras estás en sigilo."
L["What it says while you are out of stealth."] = "Lo que dice mientras no estás en sigilo."
L["What it shows as you enter combat."] = "Lo que muestra al entrar en combate."
L["What it shows as you leave combat."] = "Lo que muestra al salir de combate."
L["What Lines Show"] = "Lo que muestran las líneas"
L["What Naowh's profession window adds to each recipe: the ones you have not learned yet, your next rank, and how many of each reagent you have."] = "Lo que la ventana de profesión de Naowh añade a cada receta: las que aún no has aprendido, tu siguiente rango y cuántos tienes de cada componente."
L["What Rows Show"] = "Lo que muestran las filas"
L["What shows while you know a find but track none."] = "Lo que se muestra mientras conoces un rastreo pero no rastreas ninguno."
L["What the copy card has selected when it opens."] = "Lo que tiene seleccionado la tarjeta de copia al abrirse."
L["What the Journal lists on a boss. The same switches as the Filters icon on its title bar."] = "Lo que lista el Diario sobre un jefe. Los mismos interruptores que el icono Filtros de su barra de título."
L["What the stack fetches at the auction house, from your last Scan Prices or TradeSkillMaster."] = "Lo que se saca por el montón en la casa de subastas, según tu último Escanear precios o TradeSkillMaster."
L["What the whole stack sells for at a vendor, and each item's price."] = "Por cuánto se vende todo el montón a un vendedor, y el precio de cada objeto."
L["What to train at each level, and its cost."] = "Qué entrenar en cada nivel y su coste."
L["What you can train now and what each level brings."] = "Lo que puedes entrenar ahora y lo que trae cada nivel."
L["What you can train now, what each level brings and what it costs."] = "Lo que puedes entrenar ahora, lo que trae cada nivel y lo que cuesta."
L["What you pay the crafter for this craft, sent with the whisper. Filled in with the suggested tip; type your own as 2g 50s, 75s or 2.5 (gold). Empty it to go back to the suggestion."] = "Lo que pagas al artesano por esta fabricación, enviado con el susurro. Se rellena con la propina sugerida; escribe la tuya como 2g 50s, 75s o 2.5 (oro). Vacíalo para volver a la sugerencia."
L["What you wear that takes a better enchant for your level."] = "Lo que llevas que admite un encantamiento mejor para tu nivel."
L["What your target is doing in a fight: their short buffs and the crowd control on them."] = "Lo que hace tu objetivo en un combate: sus beneficios cortos y el control de masas sobre él."
L["Wheel"] = "Rueda"
L["Wheel on the rows"] = "Rueda sobre las filas"
L["Wheel: size. Right-click for more."] = "Rueda: tamaño. Clic derecho para más."
L["Wheel: text size. Click a line to hide it. Right-click for more."] = "Rueda: tamaño del texto. Haz clic en una línea para ocultarla. Clic derecho para más."
L["When"] = "Cuándo"
L["When a profession's skill is high enough for its next rank (Journeyman, Expert, Artisan), a banner under the skill bar and on its card in the overview says what it takes and who teaches it: the nearest trainer, book vendor or quest giver. Click Waypoint to mark them on your map. Reaching it also says so once in chat; /naowh profrank repeats that."] = "Cuando la habilidad de una profesión es suficiente para su siguiente rango (Oficial, Experto, Artesano), un aviso bajo la barra de habilidad y en su tarjeta del resumen indica lo que hace falta y quién lo enseña: el instructor, vendedor de libros o dador de misión más cercano. Haz clic en Punto de ruta para marcarlos en tu mapa. Al alcanzarlo también se indica una vez en el chat; /naowh profrank lo repite."
L["When an item on your list is up for a roll or in the loot window, and again when it is yours. Move the on-screen alert in the HUD Editor."] = "Cuando un objeto de tu lista está en tirada o en la ventana de botín, y otra vez cuando es tuyo. Mueve el aviso en pantalla en el Editor de HUD."
L["When an NPC offers several things, goes straight to a finished quest to hand in, or the first quest on offer. Works with the two options above."] = "Cuando un PNJ ofrece varias cosas, va directo a una misión terminada para entregar o a la primera misión ofrecida. Funciona con las dos opciones de arriba."
L["When it is up for a roll or drops."] = "Cuando está en tirada o cae."
L["When it is yours."] = "Cuando es tuyo."
L["When You Leave"] = "Al salir"
L["When you level up with new spells to train, a toast says how many and what they cost, with buttons to open the planner and to put a waypoint on your nearest trainer. Move it in the HUD Editor."] = "Cuando subes de nivel con hechizos nuevos que entrenar, un aviso indica cuántos y lo que cuestan, con botones para abrir el planificador y poner un punto de ruta a tu instructor más cercano. Muévelo en el Editor de HUD."
L["When you log out, the set this character saved last is saved again with your bars, macros and keybinds as they are."] = "Al desconectarte, el último conjunto que guardó este personaje se vuelve a guardar con tus barras, macros y atajos de teclado tal como están."
L["When you reach a city or inn, a flashing list in the middle of the screen of what you are short on. It stays up until you have what you need or leave. Move it in the HUD Editor."] = "Al llegar a una ciudad o posada, una lista parpadeante en el centro de la pantalla con lo que te falta. Se mantiene hasta que tengas lo que necesitas o te vayas. Muévela en el Editor de HUD."
L["When You Reset"] = "Al reiniciar"
L["Where"] = "Dónde"
L["Where %s starts is not known."] = "No se sabe dónde empieza %s."
L["Where do you want to start?"] = "¿Por dónde quieres empezar?"
L["Where it comes from is not recorded yet; try the Auction House."] = "Aún no se ha registrado de dónde sale; prueba en la casa de subastas."
L["Where It Drops"] = "Dónde cae"
L["Where on the frame the bar sits."] = "Dónde se coloca la barra en el marco."
L["Where to get them"] = "Dónde conseguirlos"
L["Where your distance to pulling aggro and the entry count sit: under the bars, or between the title bar and the bars."] = "Dónde se colocan tu distancia hasta quitar el aggro y el recuento de entradas: bajo las barras o entre la barra de título y las barras."
L["Where your star sits: on the icon's corner, before the name, or hidden."] = "Dónde va tu estrella: en la esquina del icono, antes del nombre u oculta."
L["Where? on Whispers"] = "¿Dónde? en susurros"
L["Whether a healthstone or a potion comes first."] = "Si va primero una piedra de salud o una poción."
L["Whether a new mark counts on every character or only this one."] = "Si una marca nueva cuenta en todos los personajes o solo en este."
L["Whether NF Food leaves drinks to NF Drink."] = "Si NF Food deja las bebidas a NF Drink."
L["Which crowd control shows, by ability: every rank, and the same spell from items and creatures."] = "Qué control de masas se muestra, por habilidad: todos los rangos y el mismo hechizo de objetos y criaturas."
L["Which debuffs show beside crowd control: off until you light them."] = "Qué perjuicios se muestran junto al control de masas: desactivados hasta que los ilumines."
L["Which guild and title lines show with players' names, saved by the game itself."] = "Qué líneas de hermandad y título se muestran con los nombres de los jugadores, guardadas por el propio juego."
L["Which kinds of consumable Scan Bags adds and Ask to Add asks about."] = "Qué tipos de consumible añade Escanear bolsas y por cuáles pregunta Preguntar si añadir."
L["Which mana spells get the line."] = "Qué hechizos de maná reciben la línea."
L["Which modules do you want?"] = "¿Qué módulos quieres?"
L["Which of your picks alert: your BiS only, your top two, or every pick on your list."] = "Cuáles de tus elecciones avisan: solo tu BiS, tus dos primeras o todas las de tu lista."
L["Which the macro uses first when you carry both: a healthstone or a healing potion."] = "Cuál usa primero la macro cuando llevas ambas: una piedra de salud o una poción de sanación."
L["While a merchant is open, a Buy button under the chosen recipe's reagents buys from them, in one click, every checked reagent they sell, such as Coarse Thread or Weak Flux, for as many crafts as you set beside it. The total cost shows beside the button; hover Buy for each reagent."] = "Con un mercader abierto, un botón Comprar bajo los componentes de la receta elegida le compra, con un clic, cada componente marcado que vende, como Hilo grueso o Fundente débil, para tantas fabricaciones como indiques al lado. El coste total aparece junto al botón; pasa el cursor por Comprar para ver cada componente."
L["While flying"] = "En vuelo"
L["While flying and at the campfire"] = "En vuelo y en la hoguera"
L["While Heroic Strike, Cleave, Maul or Raptor Strike is queued, the melee bars take its color and name."] = "Mientras Golpe heroico, Rajar, Machacar o Golpe de raptor está en cola, las barras cuerpo a cuerpo toman su color y nombre."
L["While the auction house is open, a Buy button under the chosen recipe's reagents buys the materials for as many crafts as you set beside it: every checked reagent that vendors do not sell. Each one shows its price first and is only bought when you click Confirm."] = "Con la casa de subastas abierta, un botón Comprar bajo los componentes de la receta elegida compra los materiales para tantas fabricaciones como indiques al lado: cada componente marcado que no venden los vendedores. Cada uno muestra antes su precio y solo se compra al pulsar Confirmar."
L["While the auction house is open, a Search AH button next to the chosen recipe's name searches it for the item the recipe makes. Unlearned recipes also get Search Recipe, for the pattern, plans or manual that teaches it. Recipes that make no item, such as enchants, get no Search AH."] = "Con la casa de subastas abierta, un botón Buscar en subasta junto al nombre de la receta elegida busca el objeto que fabrica. Las recetas no aprendidas también tienen Buscar receta, para el patrón, diseño o manual que la enseña. Las recetas que no fabrican ningún objeto, como los encantamientos, no tienen Buscar en subasta."
L["While the auction house is open, Shift-click a recipe or a reagent to search the auction house for the item: what the recipe makes, or the reagent. While you type in chat, Shift-click still links it."] = "Con la casa de subastas abierta, Mayús+clic en una receta o un componente para buscar el objeto en la casa de subastas: lo que fabrica la receta o el componente. Mientras escribes en el chat, Mayús+clic sigue enlazándolo."
L["While the mouse is away, with Show On Mouseover on."] = "Mientras el ratón está lejos, con Mostrar al pasar el cursor activado."
L["While you are in a group, shares each quest you accept from an NPC with the others, if the quest can be shared. A quest someone shared with you is not shared again. The Modifier as you accept keeps it to yourself."] = "Mientras estás en un grupo, comparte con los demás cada misión que aceptas de un PNJ, si la misión se puede compartir. Una misión que alguien compartió contigo no se vuelve a compartir. El modificador al aceptar te la guarda para ti."
L["While you carry books, a pin on who takes them: your librarian, or the mage trainer."] = "Mientras llevas libros, un marcador sobre quién los acepta: tu bibliotecario o el instructor de magos."
L["While you cast, mark where the cast ends on the Main Hand bar. It turns red when the cast will still be going as the swing comes due."] = "Mientras lanzas, marca dónde termina el lanzamiento en la barra de la mano principal. Se pone roja cuando el lanzamiento seguirá en curso al tocar el golpe."
