L["Whispers thanks when a player gives you a class buff in the open world; turn friendly nameplates on so the game can name them."] = "Susurra un agradecimiento cuando un jugador te da un beneficio de clase en el mundo abierto; activa las placas de nombre amistosas para que el juego pueda nombrarlo."
L["White: exact, from their Naowh Forever. Grey: added up from their gear."] = "Blanco: exacto, de su Naowh Forever. Gris: sumado a partir de su equipo."
L["Who the cast is aimed at, in their class color."] = "A quién va dirigido el lanzamiento, en su color de clase."
L["Whoever holds aggro in one color."] = "Quien tiene el aggro, en un color."
L["Whose ranking the picker shows. Each spec keeps its own picks on a list."] = "De quién es la clasificación que muestra el selector. Cada especialización guarda sus propias elecciones en una lista."
L["Wide kite"] = "Cometa ancha"
L["Widen the swing and Auto Shot windows by your world latency, so they show when to press rather than when the server acts."] = "Amplía las ventanas de golpe y de Disparo automático según tu latencia del mundo, para que muestren cuándo pulsar y no cuándo actúa el servidor."
