L["Crafting several at once (Create All, or Create with a count) shows one bar for the whole batch, drawn like the Flight Timer: the recipe, how many are done and the time left on all of them. It sits where the Flight Timer is, as nobody crafts in flight: move it in the HUD Editor as the Flight Timer."] = "Fabricar varios a la vez (Crear todo, o Crear con una cantidad) muestra una barra para toda la tanda, dibujada como el temporizador de vuelo: la receta, cuántos van hechos y el tiempo restante de todos. Se coloca donde está el temporizador de vuelo, ya que nadie fabrica en vuelo: muévela en el Editor de HUD como el temporizador de vuelo."
