L["Disenchants the next item in the Disenchant window while it is open, one item per press, like a click on Disenchant All."] = "Desencanta el siguiente objeto de la ventana de desencantar mientras está abierta, un objeto por pulsación, como un clic en Desencantar todo."
L["Drag to reorder within this section."] = "Arrastra para reordenar dentro de esta sección."
