L["Off thanks every caster with the /thank emote instead; needs Thank With an Emote."] = "Desactivado, agradece a cada lanzador con el emote /thank; requiere Dar las gracias con un emote."
L["On: any flask, elixir or buff food in your bags reminds you, listed or not; off: even with none."] = "Activado: cualquier frasco, elixir o comida con beneficio de tus bolsas activa el recordatorio, esté en la lista o no; desactivado: incluso sin ninguno."
