L["A .png, .tga or .blp file. Make its width and height powers of two, such as 128, 256, 512 or 1024, to be safe; a small one, 128 or 256, is good for a pattern that is repeated with Tile Image, and Tile Size says how wide each repeat is. A .jpg is most likely not read by the game: open it and save it as a .png first."] = "Un archivo .png, .tga o .blp. Para ir sobre seguro, que su anchura y altura sean potencias de dos, como 128, 256, 512 o 1024; uno pequeño, de 128 o 256, va bien para un patrón que se repite con Imagen en mosaico, y Tamaño del mosaico indica el ancho de cada repetición. Lo más probable es que el juego no lea un .jpg: ábrelo y guárdalo antes como .png."
