L["In the game's Interface\\AddOns folder make a folder of your own, such as MyBackgrounds, and put the file in it, for instance MyBackgrounds\\panel.png. A folder of your own is not touched when add-ons are updated. Restart the game once so it finds the file."] = "En la carpeta Interface\\AddOns del juego, crea una carpeta propia, como MyBackgrounds, y pon el archivo en ella, por ejemplo MyBackgrounds\\panel.png. Una carpeta propia no se toca al actualizar los addons. Reinicia el juego una vez para que encuentre el archivo."
L["In the Window card, under Picture, pick Your Own Picture in Image, and write the path from Interface in Custom Image, with backslashes and with the file's extension: Interface\\AddOns\\MyBackgrounds\\panel.png. Pick None or another picture in Image to go back."] = "En la tarjeta Ventana, en Imagen de fondo, elige Tu propia imagen en Imagen y escribe la ruta desde Interface en Imagen personalizada, con barras invertidas y con la extensión del archivo: Interface\\AddOns\\MyBackgrounds\\panel.png. Elige Ninguna u otra imagen en Imagen para volver atrás."
