L["The first row at the bottom and the rest stacked above it, as some meters do."] = "La primera fila abajo y el resto apiladas encima, como hacen algunos medidores."
L["The game did not find the file. Check the folder name, the spelling and the extension, and that the game was restarted after the file was added."] = "El juego no ha encontrado el archivo. Comprueba el nombre de la carpeta, la ortografía y la extensión, y que reiniciaste el juego tras añadir el archivo."
