L["The game's own sparkle on every quest item, kept on through graphics presets; Glimmer's Effect does not change it."] = "El destello propio del juego en cada objeto de misión, que se mantiene con cualquier preajuste gráfico; el Efecto de Fulgor no lo cambia."
L["The game's own, in your Accent, or hidden; the mouse wheel still scrolls."] = "La del juego, en tu acento u oculta; la rueda del ratón sigue desplazando."
