L["Adds it to Favorites at the top of the list, or takes it off."] = "Lo añade a Favoritos, al principio de la lista, o lo quita."
L["HOW TO PLAY\n\nSET UP A SESSION\nEnter the pool in gold-and-silver format: an integer followed by \"g\", then an integer followed by \"s\" (for example, 10g50s). One gold is 100 silver, so 10g50s is 1,050 silver. All roll limits use the pool's total silver value. Party and Raid chat are supported; choose the channel your group is using. Both pool components must be whole numbers.\n\nSelect New Game to announce the session. Players, including the host, join by saying the configured join word in the selected chat. They can leave the lobby by saying the leave word. The host can use Last Call to remind the group, then select Start Rolling once at least two players have joined.\n\nCLASSIC\nWhen the host selects Start Rolling, chat announces that everyone can roll and gives the roll limit. Every joined player rolls from 1 to the pool's total silver value using /roll. With a 10g50s pool, each player rolls from 1 to 1,050. Use Announce Rolls to remind players who still need to roll and show the roll range.\n\nWhen everyone has rolled, the player with the lowest roll pays the player with the highest roll the difference between those original rolls. The difference is silver and is announced in gold-and-silver format (for example, 50 silver is shown as 0g50s). If the highest or lowest roll is tied, only the players tied at that extreme reroll to decide that side's winner or loser. The original high and low rolls determine the amount, even if a tie-break roll changes the order. If every player rolls the same number, nobody pays and everyone rolls again.\n\nDEATHROLL\nAfter the host starts the game, two joined players are selected at random. Gamble announces the selected players, then announces which one was randomly chosen to roll first.\n\nThe first player rolls from 1 to the pool's total silver value. With a 10g50s pool, the first roll is from 1 to 1,050. The two selected players then alternate: after each roll, the next player rolls from 1 to the value just rolled. Use Announce Rolls to identify whose turn it is and the current roll range. The first player to roll 1 loses; the other player wins the pool, announced in gold-and-silver format.\n\nENDING A SESSION\nThe host can select Cancel Session at any time before the session completes. The cancellation is announced in chat and the session ends for everyone. Completed sessions cannot be cancelled.\n\nGamble only announces results; it does not transfer gold. Players settle any announced amount themselves."] = "CÓMO JUGAR\n\nPREPARAR UNA SESIÓN\nIntroduce el bote en formato de oro y plata: un número entero seguido de \"g\" y luego un número entero seguido de \"s\" (por ejemplo, 10g50s). Una moneda de oro son 100 de plata, así que 10g50s son 1050 de plata. Todos los límites de tirada usan el valor total en plata del bote. Se admiten los chats de grupo y de banda; elige el canal que usa tu grupo. Ambas partes del bote deben ser números enteros.\n\nSelecciona Nueva partida para anunciar la sesión. Los jugadores, incluido el anfitrión, se unen diciendo en el chat elegido la palabra para unirse configurada. Pueden salir de la sala diciendo la palabra para salir. El anfitrión puede usar Último aviso para recordárselo al grupo y luego seleccionar Empezar a tirar cuando se hayan unido al menos dos jugadores.\n\nCLÁSICO\nCuando el anfitrión selecciona Empezar a tirar, el chat anuncia que todos pueden tirar e indica el límite de tirada. Cada jugador unido tira con /roll del 1 al valor total en plata del bote. Con un bote de 10g50s, cada jugador tira del 1 al 1050. Usa Anunciar tiradas para recordárselo a los jugadores que aún tienen que tirar y mostrar el rango de tirada.\n\nCuando todos han tirado, el jugador con la tirada más baja paga al de la tirada más alta la diferencia entre esas tiradas originales. La diferencia está en plata y se anuncia en formato de oro y plata (por ejemplo, 50 de plata se muestra como 0g50s). Si hay empate en la tirada más alta o en la más baja, solo los jugadores empatados en ese extremo vuelven a tirar para decidir el ganador o el perdedor de ese lado. Las tiradas originales más alta y más baja determinan la cantidad, aunque una tirada de desempate cambie el orden. Si todos los jugadores sacan el mismo número, nadie paga y todos vuelven a tirar.\n\nDEATHROLL\nCuando el anfitrión inicia la partida, se eligen al azar dos jugadores unidos. Apuestas anuncia los jugadores elegidos y luego cuál de ellos, elegido al azar, tira primero.\n\nEl primer jugador tira del 1 al valor total en plata del bote. Con un bote de 10g50s, la primera tirada es del 1 al 1050. Después, los dos jugadores elegidos se alternan: tras cada tirada, el siguiente jugador tira del 1 al valor que acaba de salir. Usa Anunciar tiradas para indicar a quién le toca y el rango de tirada actual. El primer jugador que saque un 1 pierde; el otro gana el bote, anunciado en formato de oro y plata.\n\nTERMINAR UNA SESIÓN\nEl anfitrión puede seleccionar Cancelar sesión en cualquier momento antes de que termine la sesión. La cancelación se anuncia en el chat y la sesión termina para todos. Las sesiones completadas no se pueden cancelar.\n\nApuestas solo anuncia resultados; no transfiere oro. Los jugadores liquidan ellos mismos las cantidades anunciadas."
