L["Add an item ID, drag an item onto its section, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "Añade una ID de objeto, arrastra un objeto a su sección o importa una lista. La comida cuenta cualquier beneficio Bien alimentado y otros objetos su propio beneficio; añade ID de hechizos de beneficio solo para un objeto que dé otro. No se añade nada automáticamente. Pasa el cursor por un recordatorio para elegir un objeto configurado de tus bolsas. Los recordatorios se pausan en combate; los menús de objetos funcionan fuera de combate. Cuándo y dónde se muestran está en AuraBuffs > Configuración."
