L["Hide Blessings on Paladins"] = "Ocultar bendiciones en paladines"
L["Hides blessing reminders while your paladin is grouped; use the Blessings tab instead."] = "Oculta los recordatorios de bendiciones mientras tu paladín está en grupo; usa en su lugar la pestaña Bendiciones."
L["Daily Word First"] = "Primero la Palabra del día"
L["Opens the Daily Word first until today's is done; closing it opens your game."] = "Abre primero la Palabra del día hasta que completes la de hoy; al cerrarla se abre tu juego."
L["Placed when learned:"] = "Se coloca al aprenderlo:"
L["(level %d)"] = "(nivel %d)"
L["Fills in as you learn them"] = "Se completa al aprenderlos"
L["A website layout always does: each spell drops into its slot when learned."] = "Un diseño de la web siempre lo hace: cada hechizo se coloca en su casilla al aprenderlo."
L["Not available with the Gamepad interface style"] = "No disponible con el estilo de interfaz de mando"
L["The world map cannot be opened from Naowh Forever with a gamepad."] = "El mapa del mundo no se puede abrir desde Naowh Forever con un mando."
L["Show Buff Range"] = "Mostrar alcance de beneficios"
L["Shows how many missing buffs are in casting range and dims icons with none confirmed."] = "Muestra cuántos beneficios que faltan están al alcance de lanzamiento y atenúa los iconos sin ninguno confirmado."
L["Hide Out of Range"] = "Ocultar fuera de alcance"
L["Hides a raid buff until someone missing it is in casting range."] = "Oculta un beneficio de banda hasta que alguien a quien le falte esté al alcance de lanzamiento."
L["Hide in the World at Level 60"] = "Ocultar en el mundo a nivel 60"
L["At level 60, consumable reminders stay out of the open world."] = "A nivel 60, los recordatorios de consumibles no aparecen en el mundo abierto."
